// ---- Biblioteca: endereços IP que o scanner NÃO pode acessar (proteção contra SSRF) ----
// O gerador (scripts/gerar-fluxo.py) cola este trecho no começo dos nós que precisam dele.

// Converte "a.b.c.d" em número (0 a 2^32-1). Devolve null se não for IPv4 válido.
function ipv4ParaNumero(ip) {
  const partes = String(ip).split('.');
  if (partes.length !== 4) return null;
  let numero = 0;
  for (const parte of partes) {
    if (!/^\d{1,3}$/.test(parte)) return null;
    const valor = Number(parte);
    if (valor > 255) return null;
    numero = numero * 256 + valor;
  }
  return numero;
}

// Faixas IPv4 privadas, locais, reservadas ou de documentação.
const FAIXAS_IPV4_BLOQUEADAS = [
  ['0.0.0.0', 8],       // "esta rede"
  ['10.0.0.0', 8],      // privada
  ['100.64.0.0', 10],   // CGNAT
  ['127.0.0.0', 8],     // loopback
  ['169.254.0.0', 16],  // link-local (inclui metadados de nuvem 169.254.169.254)
  ['172.16.0.0', 12],   // privada (inclui as redes do Docker)
  ['192.0.0.0', 24],    // IETF
  ['192.0.2.0', 24],    // documentação
  ['192.88.99.0', 24],  // 6to4 relay
  ['192.168.0.0', 16],  // privada
  ['198.18.0.0', 15],   // testes de desempenho
  ['198.51.100.0', 24], // documentação
  ['203.0.113.0', 24],  // documentação
  ['224.0.0.0', 4],     // multicast
  ['240.0.0.0', 4],     // reservada e broadcast
];

function ipv4Bloqueado(ip) {
  const numero = ipv4ParaNumero(ip);
  if (numero === null) return true;
  return FAIXAS_IPV4_BLOQUEADAS.some(([base, bits]) => {
    const mascara = bits === 0 ? 0 : (0xffffffff << (32 - bits)) >>> 0;
    return ((numero & mascara) >>> 0) === ((ipv4ParaNumero(base) & mascara) >>> 0);
  });
}

// Expande um IPv6 para 8 grupos numéricos. Devolve null se for inválido.
function expandirIPv6(ip) {
  let texto = String(ip).replace(/^\[|\]$/g, '').toLowerCase();
  const zona = texto.indexOf('%');
  if (zona >= 0) texto = texto.slice(0, zona);
  const comIPv4 = texto.match(/^(.*:)(\d+\.\d+\.\d+\.\d+)$/);
  if (comIPv4) {
    const numero = ipv4ParaNumero(comIPv4[2]);
    if (numero === null) return null;
    texto = comIPv4[1] + (numero >>> 16).toString(16) + ':' + (numero & 0xffff).toString(16);
  }
  const metades = texto.split('::');
  if (metades.length > 2) return null;
  const esquerda = metades[0] ? metades[0].split(':') : [];
  const direita = metades.length === 2 && metades[1] ? metades[1].split(':') : [];
  const faltam = 8 - esquerda.length - direita.length;
  if (metades.length === 1 && faltam !== 0) return null;
  if (metades.length === 2 && faltam < 1) return null;
  const grupos = [...esquerda, ...Array(metades.length === 2 ? faltam : 0).fill('0'), ...direita];
  if (grupos.some((g) => !/^[0-9a-f]{1,4}$/.test(g))) return null;
  return grupos.map((g) => parseInt(g, 16));
}

function ipv6Bloqueado(ip) {
  const g = expandirIPv6(ip);
  if (!g) return true;
  const ipv4Embutido = () => `${g[6] >> 8}.${g[6] & 255}.${g[7] >> 8}.${g[7] & 255}`;
  // IPv4 mapeado (::ffff:a.b.c.d) e NAT64 (64:ff9b::a.b.c.d): vale a regra do IPv4 embutido.
  if (g.slice(0, 5).every((x) => x === 0) && g[5] === 0xffff) return ipv4Bloqueado(ipv4Embutido());
  if (g[0] === 0x64 && g[1] === 0xff9b && g.slice(2, 6).every((x) => x === 0)) return ipv4Bloqueado(ipv4Embutido());
  // Só aceita endereços globais (2000::/3). Isso já exclui ::1, fc00::/7, fe80::/10 e multicast.
  if ((g[0] & 0xe000) !== 0x2000) return true;
  if (g[0] === 0x2001 && (g[1] === 0x0db8 || g[1] === 0)) return true; // documentação e Teredo
  if (g[0] === 0x2002) return true; // 6to4 (embute um IPv4 qualquer)
  return false;
}

function ehIPv4(texto) {
  return ipv4ParaNumero(texto) !== null;
}

function ipBloqueado(ip) {
  return String(ip).includes(':') ? ipv6Bloqueado(ip) : ipv4Bloqueado(ip);
}
// ---- fim da biblioteca ----

// ---- Biblioteca: leitura ESTRITA de URLs ----
// O nó Code do n8n roda numa sandbox sem a classe URL, então a URL é lida aqui.
// A regra é "na dúvida, recusa": qualquer forma ambígua (IPv4 em octal/hexa/decimal, barra
// invertida, usuário@, caracteres não ASCII) é recusada. O endereço entregue ao nó "Buscar site"
// é remontado em formato canônico, para que o n8n acesse exatamente o host que foi validado.

const OCTETO = '(25[0-5]|2[0-4]\\d|1\\d\\d|[1-9]?\\d)';
const IPV4_ESTRITO = new RegExp(`^${OCTETO}(\\.${OCTETO}){3}$`);
const ROTULO = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$/;

function erroUrl(mensagem) {
  const erro = new Error(mensagem);
  erro.ehErroDeUrl = true;
  return erro;
}

// Devolve { protocolo, host, ehIP, porta, href } ou lança erro com mensagem amigável.
function analisarUrl(texto) {
  const bruto = String(texto ?? '').trim();
  if (/[\u0000-\u001f\u007f\s\\]/.test(bruto)) throw erroUrl('O endereço tem espaços, barra invertida ou caracteres de controle.');

  const partes = bruto.match(/^([a-z][a-z0-9+.-]*):\/\/([^/?#]*)(.*)$/i);
  if (!partes) throw erroUrl('Endereço inválido. Exemplo de endereço válido: https://exemplo.com.br');
  const protocolo = partes[1].toLowerCase();
  const autoridade = partes[2];
  let resto = partes[3].replace(/#.*$/, '');

  if (protocolo !== 'http' && protocolo !== 'https') throw erroUrl('Só são aceitos endereços que começam com http:// ou https://.');
  if (autoridade.includes('@')) throw erroUrl('O endereço não pode conter usuário ou senha.');
  if (/[^\x21-\x7e]/.test(bruto)) throw erroUrl('Use apenas caracteres ASCII. Para domínios com acento, use a forma xn-- (punycode).');

  let host;
  let porta = '';
  const ipv6 = autoridade.match(/^\[([0-9a-f:.]+)\](?::(\d*))?$/i);
  if (ipv6) {
    if (!expandirIPv6(ipv6[1])) throw erroUrl('Endereço IPv6 inválido.');
    host = ipv6[1].toLowerCase();
    porta = ipv6[2] ?? '';
  } else {
    const comPorta = autoridade.match(/^([^:]*)(?::(\d*))?$/);
    if (!comPorta) throw erroUrl('Endereço inválido.');
    host = comPorta[1].toLowerCase().replace(/\.$/, '');
    porta = comPorta[2] ?? '';
  }
  if (!host) throw erroUrl('O endereço não tem domínio.');

  const portaPadrao = protocolo === 'https' ? '443' : '80';
  porta = porta.replace(/^0+(?=\d)/, '');
  if (porta === portaPadrao) porta = '';
  if (porta && !['80', '443'].includes(porta)) throw erroUrl(`A porta ${porta} não é permitida. O scanner só analisa sites nas portas 80 e 443.`);

  let ehIP = Boolean(ipv6);
  if (!ipv6) {
    const rotulos = host.split('.');
    const ultimo = rotulos[rotulos.length - 1];
    // Como no navegador: se o último pedaço for numérico, o host é tratado como IPv4.
    if (/^(0x[0-9a-f]*|\d+)$/i.test(ultimo)) {
      if (!IPV4_ESTRITO.test(host)) throw erroUrl(`"${host}" não é um IPv4 válido no formato a.b.c.d (sem zeros à esquerda).`);
      ehIP = true;
    } else {
      if (host.length > 253 || !rotulos.every((r) => ROTULO.test(r))) throw erroUrl(`"${host}" não é um nome de domínio válido.`);
    }
  }

  if (!resto.startsWith('/')) resto = '/' + resto;
  resto = resto.replace(/[^A-Za-z0-9\-._~:/?\[\]@!$&'()*+,;=%]/g, (c) => encodeURIComponent(c));

  const hostNaUrl = ipv6 ? `[${host}]` : host;
  return { protocolo, host, ehIP, porta, href: `${protocolo}://${hostNaUrl}${porta ? ':' + porta : ''}${resto}` };
}

// Resolve o cabeçalho Location de um redirecionamento em relação à página atual (base canônica).
// Formas estranhas são devolvidas como estão: a validação seguinte as recusa.
function resolverUrl(destino, base) {
  const d = String(destino ?? '').trim();
  const origem = base.match(/^(https?:\/\/[^/?#]+)/i)[1];
  const caminhoBase = base.slice(origem.length).replace(/[?#].*$/, '') || '/';
  if (/^[a-z][a-z0-9+.-]*:/i.test(d)) return d;
  if (d.startsWith('\\') || d.startsWith('/\\')) return d;
  if (d.startsWith('//')) return base.split(':')[0] + ':' + d;
  if (d.startsWith('/')) return origem + d;
  if (d.startsWith('?')) return origem + caminhoBase + d;
  if (d.startsWith('#') || d === '') return base;
  return origem + caminhoBase.replace(/[^/]*$/, '') + d;
}
// ---- fim da biblioteca ----

// Nó "Validar URL": confere o endereço ANTES de qualquer acesso.
// Aceita só http/https nas portas padrão e recusa nomes e IPs internos (proteção contra SSRF).
// Roda de novo a cada redirecionamento, porque um site público pode redirecionar para um endereço interno.
const entrada = $input.first().json;
const bruto = String(entrada.url ?? '').trim();
const saltos = Number(entrada.saltos ?? 0);
const urlOriginal = entrada.urlOriginal ?? bruto;
const cadeia = Array.isArray(entrada.cadeia) ? entrada.cadeia : [];

function falha(motivo) {
  return [{ json: { ok: false, motivo, url: bruto, urlOriginal, saltos, cadeia } }];
}

if (!bruto) return falha('Informe o endereço do site.');
if (bruto.length > 2048) return falha('O endereço é longo demais (máximo de 2048 caracteres).');

let url;
try {
  // Sem "http://" ou "https://", assume https.
  url = analisarUrl(/^[a-z][a-z0-9+.-]*:\/\//i.test(bruto) ? bruto : 'https://' + bruto);
} catch (erro) {
  if (!erro.ehErroDeUrl) throw erro;
  return falha(erro.message);
}

if (url.ehIP) {
  if (ipBloqueado(url.host)) {
    return falha(`O endereço ${url.host} é interno ou reservado. Por segurança, o scanner só analisa sites públicos.`);
  }
} else {
  const sufixosInternos = ['localhost', '.local', '.internal', '.intranet', '.lan', '.home', '.corp', '.home.arpa', '.localdomain', '.test', '.invalid', '.example'];
  if (!url.host.includes('.') || sufixosInternos.some((s) => url.host === s.replace(/^\./, '') || url.host.endsWith(s))) {
    return falha(`O nome "${url.host}" parece ser de uma rede interna. Por segurança, o scanner só analisa sites públicos com domínio completo (ex.: exemplo.com.br).`);
  }
}

return [{
  json: {
    ok: true,
    url: url.href,
    host: url.host,
    ehIP: url.ehIP,
    urlOriginal,
    saltos,
    cadeia,
  },
}];

