  const grupos = [...esquerda, ...Array(metades.length === 2 ? faltam : 0).fill('0'), ...direita];
  if (grupos.some((g) => !/^[0-9a-f]{1,4}$/.test(g))) return null;
  return grupos.map((g) => parseInt(g, 16));
}

function ipv6Bloqueado(ip) {
  const g = expandirIPv6(ip);
  if (!g) return true;
  const ipv4Embutido = () => `${g[6] >> 8}.${g[6] & 255}.${g[7] >> 8}.${g[7] & 255}`;
  // IPv4 mapeado (::ffff:a.b.c.d) e NAT64 (64:ff9b::a.b.c.d): vale a regra do IPv4 embutido.
  if (g.slice(0, 5).every((x) => x === 0) && g[5] === 0xffff) return ipv4Bloqueado(ipv4Embutido());
  if (g[0] === 0x64 && g[1] === 0xff9b && g.slice(2, 6).every((x) => x === 0)) return ipv4Bloqueado(ipv4Embutido());
  // Só aceita endereços globais (2000::/3). Isso já exclui ::1, fc00::/7, fe80::/10 e multicast.
  if ((g[0] & 0xe000) !== 0x2000) return true;
  if (g[0] === 0x2001 && (g[1] === 0x0db8 || g[1] === 0)) return true; // documentação e Teredo
  if (g[0] === 0x2002) return true; // 6to4 (embute um IPv4 qualquer)
  return false;
}

function ehIPv4(texto) {
  return ipv4ParaNumero(texto) !== null;
}

function ipBloqueado(ip) {
  return String(ip).includes(':') ? ipv6Bloqueado(ip) : ipv4Bloqueado(ip);
}
// ---- fim da biblioteca ----

// ---- Biblioteca: leitura ESTRITA de URLs ----
// O nó Code do n8n roda numa sandbox sem a classe URL, então a URL é lida aqui.
// A regra é "na dúvida, recusa": qualquer forma ambígua (IPv4 em octal/hexa/decimal, barra
// invertida, usuário@, caracteres não ASCII) é recusada. O endereço entregue ao nó "Buscar site"
// é remontado em formato canônico, para que o n8n acesse exatamente o host que foi validado.

const OCTETO = '(25[0-5]|2[0-4]\\d|1\\d\\d|[1-9]?\\d)';
const IPV4_ESTRITO = new RegExp(`^${OCTETO}(\\.${OCTETO}){3}$`);
const ROTULO = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$/;

function erroUrl(mensagem) {
  const erro = new Error(mensagem);
  erro.ehErroDeUrl = true;
  return erro;
}

// Devolve { protocolo, host, ehIP, porta, href } ou lança erro com mensagem amigável.
function analisarUrl(texto) {
  const bruto = String(texto ?? '').trim();
  if (/[\u0000-\u001f\u007f\s\\]/.test(bruto)) throw erroUrl('O endereço tem espaços, barra invertida ou caracteres de controle.');

  const partes = bruto.match(/^([a-z][a-z0-9+.-]*):\/\/([^/?#]*)(.*)$/i);
  if (!partes) throw erroUrl('Endereço inválido. Exemplo de endereço válido: https://exemplo.com.br');
  const protocolo = partes[1].toLowerCase();
  const autoridade = partes[2];
  let resto = partes[3].replace(/#.*$/, '');

  if (protocolo !== 'http' && protocolo !== 'https') throw erroUrl('Só são aceitos endereços que começam com http:// ou https://.');
  if (autoridade.includes('@')) throw erroUrl('O endereço não pode conter usuário ou senha.');
  if (/[^\x21-\x7e]/.test(bruto)) throw erroUrl('Use apenas caracteres ASCII. Para domínios com acento, use a forma xn-- (punycode).');

  let host;
  let porta = '';
  const ipv6 = autoridade.match(/^\[([0-9a-f:.]+)\](?::(\d*))?$/i);
  if (ipv6) {
    if (!expandirIPv6(ipv6[1])) throw erroUrl('Endereço IPv6 inválido.');
    host = ipv6[1].toLowerCase();
    porta = ipv6[2] ?? '';
  } else {
    const comPorta = autoridade.match(/^([^:]*)(?::(\d*))?$/);
    if (!comPorta) throw erroUrl('Endereço inválido.');
    host = comPorta[1].toLowerCase().replace(/\.$/, '');
    porta = comPorta[2] ?? '';
  }
  if (!host) throw erroUrl('O endereço não tem domínio.');

  const portaPadrao = protocolo === 'https' ? '443' : '80';
  porta = porta.replace(/^0+(?=\d)/, '');
  if (porta === portaPadrao) porta = '';
  if (porta && !['80', '443'].includes(porta)) throw erroUrl(`A porta ${porta} não é permitida. O scanner só analisa sites nas portas 80 e 443.`);

  let ehIP = Boolean(ipv6);
  if (!ipv6) {
    const rotulos = host.split('.');
    const ultimo = rotulos[rotulos.length - 1];
    // Como no navegador: se o último pedaço for numérico, o host é tratado como IPv4.
    if (/^(0x[0-9a-f]*|\d+)$/i.test(ultimo)) {
      if (!IPV4_ESTRITO.test(host)) throw erroUrl(`"${host}" não é um IPv4 válido no formato a.b.c.d (sem zeros à esquerda).`);
      ehIP = true;
    } else {
      if (host.length > 253 || !rotulos.every((r) => ROTULO.test(r))) throw erroUrl(`"${host}" não é um nome de domínio válido.`);
    }
  }

  if (!resto.startsWith('/')) resto = '/' + resto;
  resto = resto.replace(/[^A-Za-z0-9\-._~:/?\[\]@!$&'()*+,;=%]/g, (c) => encodeURIComponent(c));

  const hostNaUrl = ipv6 ? `[${host}]` : host;
  return { protocolo, host, ehIP, porta, href: `${protocolo}://${hostNaUrl}${porta ? ':' + porta : ''}${resto}` };
}

// Resolve o cabeçalho Location de um redirecionamento em relação à página atual (base canônica).
// Formas estranhas são devolvidas como estão: a validação seguinte as recusa.
function resolverUrl(destino, base) {
  const d = String(destino ?? '').trim();
  const origem = base.match(/^(https?:\/\/[^/?#]+)/i)[1];
  const caminhoBase = base.slice(origem.length).replace(/[?#].*$/, '') || '/';
  if (/^[a-z][a-z0-9+.-]*:/i.test(d)) return d;
  if (d.startsWith('\\') || d.startsWith('/\\')) return d;
  if (d.startsWith('//')) return base.split(':')[0] + ':' + d;
  if (d.startsWith('/')) return origem + d;
  if (d.startsWith('?')) return origem + caminhoBase + d;
  if (d.startsWith('#') || d === '') return base;
  return origem + caminhoBase.replace(/[^/]*$/, '') + d;
}
// ---- fim da biblioteca ----

// Nó "Tratar resposta": decide se segue um redirecionamento ou se parte para a análise.
// O nó "Buscar site" NÃO segue redirecionamentos sozinho: cada novo endereço volta para
// "Validar URL" e "Verificar DNS" antes de ser acessado (no máximo 5 vezes).
const MAX_REDIRECIONAMENTOS = 5;
const alvo = $('Verificar DNS').last().json;
const config = $('Configuração').first().json;
const resposta = $input.first().json;

const status = Number(resposta.statusCode ?? 0);
const cabecalhos = {};
for (const [nome, valor] of Object.entries(resposta.headers ?? {})) {
  cabecalhos[nome.toLowerCase()] = valor;
}
const cadeia = [...(alvo.cadeia ?? []), { url: alvo.url, status }];

const local = Array.isArray(cabecalhos.location) ? cabecalhos.location[0] : cabecalhos.location;
const ehRedirecionamento = [301, 302, 303, 307, 308].includes(status) && local;

if (ehRedirecionamento && alvo.saltos < MAX_REDIRECIONAMENTOS) {
  const proxima = resolverUrl(local, alvo.url);
  if (proxima) {
    return [{
      json: {
        acao: 'redirecionar',
        url: proxima,
        urlOriginal: alvo.urlOriginal,
        saltos: alvo.saltos + 1,
        cadeia,
      },
    }];
  }
}

// Texto da página, sem imagens embutidas em base64 (gastam tokens e não ajudam a análise).
let conteudo = typeof resposta.data === 'string' ? resposta.data
  : typeof resposta.body === 'string' ? resposta.body
  : JSON.stringify(resposta.data ?? resposta.body ?? '');
const tamanhoConteudo = conteudo.length;
conteudo = conteudo.replace(/data:[a-z0-9.+\/-]+;base64,[a-z0-9+\/=\s]{200,}/gi, 'data:[base64 removido]');
const limite = Number(config.limiteConteudo) || 60000;
const conteudoTruncado = conteudo.length > limite;
if (conteudoTruncado) conteudo = conteudo.slice(0, limite);

const cabecalhosFormatados = Object.entries(cabecalhos)
  .flatMap(([nome, valor]) => (Array.isArray(valor) ? valor : [valor]).map((v) => `${nome}: ${v}`))
  .join('\n');

return [{
  json: {
    acao: 'analisar',
    urlOriginal: alvo.urlOriginal,
    urlFinal: alvo.url,
    host: alvo.host,
    ips: alvo.ips,
    status,
    statusMessage: resposta.statusMessage ?? '',
    cabecalhos,
    cabecalhosFormatados,
    conteudo,
    conteudoTruncado,
    tamanhoConteudo,
    cadeia,
    parouNoLimite: Boolean(ehRedirecionamento),
    visitado: true,
    dnssec: Boolean(alvo.dnssec),
    avisoDns: alvo.avisoDns ?? '',
  },
}];

// ---- Biblioteca: endereços IP que o scanner NÃO pode acessar (proteção contra SSRF) ----
// O gerador (scripts/gerar-fluxo.py) cola este trecho no começo dos nós que precisam dele.

// Converte "a.b.c.d" em número (0 a 2^32-1). Devolve null se não for IPv4 válido.
function ipv4ParaNumero(ip) {
  const partes = String(ip).split('.');
  if (partes.length !== 4) return null;
  let numero = 0;
  for (const parte of partes) {
    if (!/^\d{1,3}$/.test(parte)) return null;
    const valor = Number(parte);
    if (valor > 255) return null;
    numero = numero * 256 + valor;
  }
  return numero;
}

// Faixas IPv4 privadas, locais, reservadas ou de documentação.
const FAIXAS_IPV4_BLOQUEADAS = [
  ['0.0.0.0', 8],       // "esta rede"
  ['10.0.0.0', 8],      // privada
  ['100.64.0.0', 10],   // CGNAT
  ['127.0.0.0', 8],     // loopback
  ['169.254.0.0', 16],  // link-local (inclui metadados de nuvem 169.254.169.254)
  ['172.16.0.0', 12],   // privada (inclui as redes do Docker)
  ['192.0.0.0', 24],    // IETF
  ['192.0.2.0', 24],    // documentação
  ['192.88.99.0', 24],  // 6to4 relay
  ['192.168.0.0', 16],  // privada
  ['198.18.0.0', 15],   // testes de desempenho
  ['198.51.100.0', 24], // documentação
  ['203.0.113.0', 24],  // documentação
  ['224.0.0.0', 4],     // multicast
  ['240.0.0.0', 4],     // reservada e broadcast
];

function ipv4Bloqueado(ip) {
  const numero = ipv4ParaNumero(ip);
  if (numero === null) return true;
  return FAIXAS_IPV4_BLOQUEADAS.some(([base, bits]) => {
    const mascara = bits === 0 ? 0 : (0xffffffff << (32 - bits)) >>> 0;
    return ((numero & mascara) >>> 0) === ((ipv4ParaNumero(base) & mascara) >>> 0);
  });
}

// Expande um IPv6 para 8 grupos numéricos. Devolve null se for inválido.
function expandirIPv6(ip) {
  let texto = String(ip).replace(/^\[|\]$/g, '').toLowerCase();
  const zona = texto.indexOf('%');
  if (zona >= 0) texto = texto.slice(0, zona);
  const comIPv4 = texto.match(/^(.*:)(\d+\.\d+\.\d+\.\d+)$/);
  if (comIPv4) {
    const numero = ipv4ParaNumero(comIPv4[2]);
    if (numero === null) return null;
    texto = comIPv4[1] + (numero >>> 16).toString(16) + ':' + (numero & 0xffff).toString(16);
  }
  const metades = texto.split('::');
  if (metades.length > 2) return null;
  const esquerda = metades[0] ? metades[0].split(':') : [];
  const direita = metades.length === 2 && metades[1] ? metades[1].split(':') : [];
  const faltam = 8 - esquerda.length - direita.length;
  if (metades.length === 1 && faltam !== 0) return null;
  if (metades.length === 2 && faltam < 1) return null;
  const grupos = [...esquerda, ...Array(metades.length === 2 ? faltam : 0).fill('0'), ...direita];
  if (grupos.some((g) => !/^[0-9a-f]{1,4}$/.test(g))) return null;
  return grupos.map((g) => parseInt(g, 16));
}

function ipv6Bloqueado(ip) {
  const g = expandirIPv6(ip);
  if (!g) return true;
  const ipv4Embutido = () => `${g[6] >> 8}.${g[6] & 255}.${g[7] >> 8}.${g[7] & 255}`;
  // IPv4 mapeado (::ffff:a.b.c.d) e NAT64 (64:ff9b::a.b.c.d): vale a regra do IPv4 embutido.
  if (g.slice(0, 5).every((x) => x === 0) && g[5] === 0xffff) return ipv4Bloqueado(ipv4Embutido());
  if (g[0] === 0x64 && g[1] === 0xff9b && g.slice(2, 6).every((x) => x === 0)) return ipv4Bloqueado(ipv4Embutido());
  // Só aceita endereços globais (2000::/3). Isso já exclui ::1, fc00::/7, fe80::/10 e multicast.
  if ((g[0] & 0xe000) !== 0x2000) return true;
  if (g[0] === 0x2001 && (g[1] === 0x0db8 || g[1] === 0)) return true; // documentação e Teredo
  if (g[0] === 0x2002) return true; // 6to4 (embute um IPv4 qualquer)
  return false;
}

function ehIPv4(texto) {
  return ipv4ParaNumero(texto) !== null;
}

function ipBloqueado(ip) {
  return String(ip).includes(':') ? ipv6Bloqueado(ip) : ipv4Bloqueado(ip);
}
// ---- fim da biblioteca ----

// ---- Biblioteca: domínio, IDs para APIs e IOCs em formato seguro ----

// Segundos níveis comuns em domínios de país (com.br, co.uk...). É uma aproximação da
// Public Suffix List, suficiente para achar o domínio registrado (whois/RDAP, VirusTotal, SPF/DMARC).
const SEGUNDO_NIVEL = new Set([
  'com', 'net', 'org', 'gov', 'edu', 'mil', 'co', 'ac', 'or', 'ne', 'go', 'gob', 'nom', 'ltd', 'plc', 'sch',
  'art', 'blog', 'app', 'dev', 'eco', 'emp', 'ind', 'inf', 'adv', 'eng', 'med', 'tur', 'tv', 'arq', 'jus', 'leg', 'mp',
]);

// "www.loja.exemplo.com.br" -> "exemplo.com.br";  "a.b.exemplo.com" -> "exemplo.com"
function dominioRegistravel(host) {
  const rotulos = String(host ?? '').toLowerCase().replace(/\.$/, '').split('.').filter(Boolean);
  if (rotulos.length <= 2) return rotulos.join('.');
  const tld = rotulos[rotulos.length - 1];
  const segundo = rotulos[rotulos.length - 2];
  const tamanho = tld.length === 2 && SEGUNDO_NIVEL.has(segundo) ? 3 : 2;
  return rotulos.slice(-tamanho).join('.');
}

// ID de URL do VirusTotal: base64url da URL, sem "=" no final.
// Feito à mão porque a sandbox do nó Code nem sempre tem Buffer/btoa. A URL chega canônica (só ASCII).
function base64Url(texto) {
  const tabela = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
  const bytes = [];
  for (const c of String(texto)) {
    const codigo = c.charCodeAt(0);
    if (codigo < 0x80) bytes.push(codigo);
    else for (const b of unescape(encodeURIComponent(c))) bytes.push(b.charCodeAt(0));
  }
  let saida = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const n = (bytes[i] << 16) | ((bytes[i + 1] ?? 0) << 8) | (bytes[i + 2] ?? 0);
    saida += tabela[(n >> 18) & 63] + tabela[(n >> 12) & 63];
    if (i + 1 < bytes.length) saida += tabela[(n >> 6) & 63];
    if (i + 2 < bytes.length) saida += tabela[n & 63];
  }
  return saida;
}

// IOC "desarmado" para colar em chamado, e-mail ou chat sem virar link clicável:
// https://mal.com/x -> hxxps://mal[.]com/x ;  1.2.3.4 -> 1.2.3[.]4
function desarmar(ioc) {
  const texto = String(ioc ?? '');
  const url = texto.match(/^(https?)(:\/\/)([^/?#]*)(.*)$/i);
  if (!url) return texto.replace(/\./g, '[.]');
  return url[1].replace(/tt/i, 'xx') + url[2] + url[3].replace(/\./g, '[.]') + url[4];
}

// Escapa caracteres de controle e corta textos vindos de APIs/sites antes de irem para a IA.
function textoCurto(texto, maximo = 200) {
  return String(texto ?? '').replace(/[\u0000-\u001f\u007f<>`]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, maximo);
}
// ---- fim da biblioteca ----

// Nó "Preparar consultas": ponto único de onde partem as consultas de inteligência.
// Recebe a página final (de "Tratar resposta") ou o alvo sem visita (modo "só reputação")
// e calcula o que cada fonte precisa: domínio registrado, IP principal, ID da URL no VirusTotal.
// As fontes são só CONSULTADAS: nenhuma URL é enviada para análise pública.
const pagina = $input.first().json;
const config = $('Configuração').first().json;
const host = String(pagina.host ?? '').toLowerCase();
const ehIP = ehIPv4(host) || host.includes(':');
const dominio = ehIP ? host : dominioRegistravel(host);
const ips = Array.isArray(pagina.ips) ? pagina.ips : [];
const ipPrincipal = ips.find(ehIPv4) ?? ips[0] ?? '';

// Hosts diferentes que apareceram nos redirecionamentos (encurtadores, rastreadores, cadeias de phishing).
const hostsCadeia = [];
for (const passo of pagina.cadeia ?? []) {
  const h = String(passo.url ?? '').match(/^https?:\/\/([^/:?#]+)/i)?.[1]?.toLowerCase();
  if (h && h !== host && !hostsCadeia.includes(h)) hostsCadeia.push(h);
}

return [{
  json: {
    ...pagina,
    modo: config.modo,
    contexto: config.contexto ?? '',
    ehIP,
    dominio,
    ipPrincipal,
    hostsCadeia,
    vtUrlId: base64Url(pagina.urlFinal),
    vtEntidade: ehIP ? `ip_addresses/${encodeURIComponent(host)}` : `domains/${encodeURIComponent(dominio)}`,
    rdap: ehIP ? `ip/${encodeURIComponent(host)}` : `domain/${encodeURIComponent(dominio)}`,
    observatorio: Boolean(pagina.visitado) && !ehIP,
    // urlscan.io: análise nova só no modo completo (o navegador do urlscan abre o site).
    // Nunca "public": só "private" (padrão) ou "unlisted".
    urlscanAnalisar: Boolean(pagina.visitado),
    urlscanVisibilidade: config.urlscanVisibilidade === 'unlisted' ? 'unlisted' : 'private',
    // Cache por URL e por modo (o modo completo guarda a análise privada do urlscan; o outro, não).
    chaveCache: `${config.prefixoCache || 'scanner:'}intel:${config.modo === 'completa' ? 'completa' : 'reputacao'}:${base64Url(pagina.urlFinal)}`,
  },
}];

// Nó "Usar cache": lê o que o Redis devolveu para esta URL (respostas das fontes de reputação
// guardadas numa análise recente). Se não houver, se estiver estragado ou se o Redis falhou,
// segue como "sem cache" e as fontes são consultadas normalmente.
const VERSAO = 1;
const alvo = $('Preparar consultas').first().json;
const bruto = $input.first().json.cache;

let hit = false;
let respostas = {};
let em = '';
if (typeof bruto === 'string' && bruto.trim()) {
  try {
    const dados = JSON.parse(bruto);
    if (dados.versao === VERSAO && dados.urlFinal === alvo.urlFinal && dados.respostas && typeof dados.respostas === 'object') {
      hit = true;
      respostas = dados.respostas;
      em = String(dados.em ?? '');
    }
  } catch (erro) { /* cache estragado: ignora */ }
}

return [{ json: { hit, respostas, em, chave: alvo.chaveCache } }];

// Nó "Processar resultados": postura de segurança calculada A PARTIR DOS CABEÇALHOS REAIS (nota A+ a F).
// Não depende da IA (a IA pode errar ou inventar). No modo "só reputação" o site não foi visitado
// e não há cabeçalhos: a postura fica "N/A".
const dados = $('Preparar consultas').first().json;
const cab = dados.cabecalhos ?? {};
const visitado = dados.visitado !== false;
const ehHttps = String(dados.urlFinal).startsWith('https://');

function valor(nome) {
  const v = cab[nome];
  if (v === undefined || v === null) return '';
  return Array.isArray(v) ? v.join(', ') : String(v);
}

const CABECALHOS = [
  'content-security-policy',
  'strict-transport-security',
  'x-content-type-options',
  'x-frame-options',
  'referrer-policy',
  'permissions-policy',
  'cross-origin-opener-policy',
  'cross-origin-embedder-policy',
  'cross-origin-resource-policy',
  'x-permitted-cross-domain-policies',
  'x-xss-protection',
];
const status = {};
for (const nome of CABECALHOS) status[nome] = { presente: valor(nome) !== '', valor: valor(nome) };

const csp = status['content-security-policy'].valor.toLowerCase();
const temFrameAncestors = /(^|;)\s*frame-ancestors\s/.test(csp);
const achados = [];
const achado = (nivel, titulo, detalhe, correcao = '') => achados.push({ nivel, titulo, detalhe, correcao });

// ---- Transporte ----
if (!ehHttps) {
  achado('alto', 'Site sem HTTPS',
    'A página final é servida por HTTP sem criptografia. Senhas, cookies e o próprio conteúdo podem ser lidos ou alterados no caminho.',
    'Instale um certificado TLS (ex.: Let\'s Encrypt) e redirecione todo o tráfego HTTP para HTTPS.');
}

// ---- Cabeçalhos de segurança ----
if (!status['content-security-policy'].presente) {
  achado('alto', 'Content-Security-Policy ausente',
    'Sem CSP, o navegador executa qualquer script injetado na página, o que facilita ataques de XSS.',
    "Content-Security-Policy: default-src 'self'; object-src 'none'; base-uri 'self'; frame-ancestors 'self'");
} else {
  const diretivaScript = (csp.match(/(?:^|;)\s*script-src\s+([^;]*)/) ?? csp.match(/(?:^|;)\s*default-src\s+([^;]*)/) ?? [])[1] ?? '';
  if (diretivaScript.includes("'unsafe-inline'") && !/'nonce-|'sha(256|384|512)-|'strict-dynamic'/.test(diretivaScript)) {
    achado('medio', "CSP permite scripts inline ('unsafe-inline')",
      'A política existe, mas aceita scripts escritos dentro do HTML. Isso anula boa parte da proteção contra XSS.',
      "Troque 'unsafe-inline' por nonces ou hashes: script-src 'self' 'nonce-<valor-aleatório>'");
  }
  if (diretivaScript.includes("'unsafe-eval'")) {
    achado('medio', "CSP permite eval ('unsafe-eval')",
      'Permite transformar texto em código JavaScript em tempo de execução, o que amplia o impacto de um XSS.',
      "Remova 'unsafe-eval' e evite eval(), new Function() e setTimeout com texto.");
  }
}

if (ehHttps) {
  if (!status['strict-transport-security'].presente) {
    achado('alto', 'Strict-Transport-Security (HSTS) ausente',
      'Sem HSTS, o primeiro acesso pode ser feito por HTTP e interceptado (ataque de downgrade / SSL stripping).',
      'Strict-Transport-Security: max-age=31536000; includeSubDomains');
  } else {
    const maxAge = Number((status['strict-transport-security'].valor.match(/max-age=(\d+)/i) ?? [])[1] ?? 0);
    if (maxAge < 15552000) {
      achado('baixo', 'HSTS com validade curta',
        `max-age=${maxAge} segundos (${Math.round(maxAge / 86400)} dias). O recomendado é pelo menos 6 meses; o ideal é 1 ano.`,
        'Strict-Transport-Security: max-age=31536000; includeSubDomains');
    }
  }
}

if (status['x-content-type-options'].valor.toLowerCase().trim() !== 'nosniff') {
  achado('medio', 'X-Content-Type-Options ausente ou inválido',
    'O navegador pode "adivinhar" o tipo de um arquivo e executar como script algo que deveria ser texto ou imagem.',
    'X-Content-Type-Options: nosniff');
}

if (!status['x-frame-options'].presente && !temFrameAncestors) {
  achado('medio', 'Proteção contra clickjacking ausente',
    'Nem X-Frame-Options nem a diretiva frame-ancestors da CSP estão definidos. Outro site pode exibir esta página dentro de um iframe invisível e induzir cliques.',
    "Content-Security-Policy: frame-ancestors 'self'   (ou X-Frame-Options: SAMEORIGIN)");
}

if (!status['referrer-policy'].presente) {
  achado('baixo', 'Referrer-Policy ausente',
    'O endereço completo da página (que pode ter parâmetros sensíveis) pode ser enviado a outros sites nos links.',
    'Referrer-Policy: strict-origin-when-cross-origin');
}

if (!status['permissions-policy'].presente) {
  achado('baixo', 'Permissions-Policy ausente',
    'Não há restrição de recursos do navegador (câmera, microfone, localização) para a página e iframes.',
    'Permissions-Policy: camera=(), microphone=(), geolocation=()');
}

if (status['x-xss-protection'].presente && !/^\s*0\s*$/.test(status['x-xss-protection'].valor)) {
  achado('info', 'X-XSS-Protection é obsoleto',
    'Navegadores modernos ignoram este cabeçalho e o filtro antigo já causou falhas. A proteção correta é a CSP.',
    'Remova o cabeçalho ou use X-XSS-Protection: 0');
}

// ---- Vazamento de informações ----
for (const nome of ['server', 'x-powered-by', 'x-aspnet-version', 'x-aspnetmvc-version', 'x-generator']) {
  const v = valor(nome);
  if (v && (/\d/.test(v) || nome !== 'server')) {
    achado('baixo', `Cabeçalho ${nome} revela tecnologia`,
      `Valor: "${v}". Saber a tecnologia e a versão ajuda um atacante a procurar falhas conhecidas.`,
      `Remova o cabeçalho ${nome} ou esconda a versão na configuração do servidor.`);
  }
}

// ---- CORS ----
if (valor('access-control-allow-origin').trim() === '*') {
  const comCredenciais = valor('access-control-allow-credentials').toLowerCase() === 'true';
  achado(comCredenciais ? 'alto' : 'info', 'CORS liberado para qualquer origem',
    comCredenciais
      ? 'Access-Control-Allow-Origin: * junto com Allow-Credentials: true é uma configuração perigosa.'
      : 'Qualquer site pode ler as respostas desta página pelo navegador. Só é aceitável para conteúdo público (ex.: CDN).',
    'Liste explicitamente as origens permitidas em Access-Control-Allow-Origin.');
}

// ---- Cookies ----
const cookies = [].concat(cab['set-cookie'] ?? []).map(String);
for (const cookie of cookies) {
  const nome = cookie.split('=')[0].trim() || '(sem nome)';
  const atributos = cookie.toLowerCase();
  const faltando = [];
  if (ehHttps && !/;\s*secure/.test(atributos)) faltando.push('Secure');
  if (!/;\s*httponly/.test(atributos)) faltando.push('HttpOnly');
  if (!/;\s*samesite=/.test(atributos)) faltando.push('SameSite');
  if (faltando.length) {
    achado(faltando.includes('Secure') ? 'medio' : 'baixo', `Cookie "${nome}" sem ${faltando.join(', ')}`,
      'Secure impede envio por HTTP; HttpOnly impede leitura por JavaScript (roubo via XSS); SameSite reduz CSRF. HttpOnly pode faltar de propósito se o cookie precisa ser lido pelo JavaScript.',
      `Set-Cookie: ${nome}=...; Secure; HttpOnly; SameSite=Lax`);
  }
}

// ---- Nota (A+ a F), parecida com a do securityheaders.com ----
const presente = (nome) => status[nome].presente;
const criticos = [
  presente('content-security-policy'),
  !ehHttps || presente('strict-transport-security'),
  status['x-content-type-options'].valor.toLowerCase().trim() === 'nosniff',
  presente('x-frame-options') || temFrameAncestors,
].filter(Boolean).length;
const importantes = [presente('referrer-policy'), presente('permissions-policy')].filter(Boolean).length;
const temProblemaCSP = achados.some((a) => a.titulo.startsWith('CSP permite'));

let nota;
if (criticos === 4) {
  if (importantes === 2) nota = temProblemaCSP ? 'A-' : 'A+';
  else if (importantes === 1) nota = temProblemaCSP ? 'B+' : 'A-';
  else nota = temProblemaCSP ? 'B' : 'B+';
} else if (criticos === 3) nota = importantes >= 1 ? 'B' : 'C+';
else if (criticos === 2) nota = 'C';
else if (criticos === 1) nota = 'D';
else nota = 'F';

// Sem HTTPS a nota não passa de D.
const ORDEM = ['A+', 'A', 'A-', 'B+', 'B', 'B-', 'C+', 'C', 'C-', 'D', 'F'];
if (!ehHttps && ORDEM.indexOf(nota) < ORDEM.indexOf('D')) nota = 'D';

if (!visitado) {
  nota = 'N/A';
  achados.length = 0;
}

const ordemNivel = { alto: 0, medio: 1, baixo: 2, info: 3 };
achados.sort((a, b) => ordemNivel[a.nivel] - ordemNivel[b.nivel]);

return [{
  json: {
    auditoria: {
      urlOriginal: dados.urlOriginal,
      urlFinal: dados.urlFinal,
      host: dados.host,
      ips: dados.ips,
      status: dados.status,
      statusMessage: dados.statusMessage,
      cadeia: dados.cadeia,
      parouNoLimite: dados.parouNoLimite,
      conteudoTruncado: dados.conteudoTruncado,
      tamanhoConteudo: dados.tamanhoConteudo,
      dataHora: new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', dateStyle: 'long', timeStyle: 'short' }),
      ehHttps,
      nota,
      totalAlto: achados.filter((a) => a.nivel === 'alto').length,
      totalMedio: achados.filter((a) => a.nivel === 'medio').length,
      totalBaixo: achados.filter((a) => a.nivel === 'baixo').length,
      achados,
      statusCabecalhos: status,
      cabecalhos: cab,
      visitado,
      modo: dados.modo,
      contexto: dados.contexto,
      ehIP: dados.ehIP,
      dominio: dados.dominio,
      ipPrincipal: dados.ipPrincipal,
      hostsCadeia: dados.hostsCadeia,
      dnssec: dados.dnssec,
      avisoDns: dados.avisoDns,
    },
  },
}];

// ---- Biblioteca: domínio, IDs para APIs e IOCs em formato seguro ----

// Segundos níveis comuns em domínios de país (com.br, co.uk...). É uma aproximação da
// Public Suffix List, suficiente para achar o domínio registrado (whois/RDAP, VirusTotal, SPF/DMARC).
const SEGUNDO_NIVEL = new Set([
  'com', 'net', 'org', 'gov', 'edu', 'mil', 'co', 'ac', 'or', 'ne', 'go', 'gob', 'nom', 'ltd', 'plc', 'sch',
  'art', 'blog', 'app', 'dev', 'eco', 'emp', 'ind', 'inf', 'adv', 'eng', 'med', 'tur', 'tv', 'arq', 'jus', 'leg', 'mp',
]);

// "www.loja.exemplo.com.br" -> "exemplo.com.br";  "a.b.exemplo.com" -> "exemplo.com"
function dominioRegistravel(host) {
  const rotulos = String(host ?? '').toLowerCase().replace(/\.$/, '').split('.').filter(Boolean);
  if (rotulos.length <= 2) return rotulos.join('.');
  const tld = rotulos[rotulos.length - 1];
  const segundo = rotulos[rotulos.length - 2];
  const tamanho = tld.length === 2 && SEGUNDO_NIVEL.has(segundo) ? 3 : 2;
  return rotulos.slice(-tamanho).join('.');
}

// ID de URL do VirusTotal: base64url da URL, sem "=" no final.
// Feito à mão porque a sandbox do nó Code nem sempre tem Buffer/btoa. A URL chega canônica (só ASCII).
function base64Url(texto) {
  const tabela = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';
  const bytes = [];
  for (const c of String(texto)) {
    const codigo = c.charCodeAt(0);
    if (codigo < 0x80) bytes.push(codigo);
    else for (const b of unescape(encodeURIComponent(c))) bytes.push(b.charCodeAt(0));
  }
  let saida = '';
  for (let i = 0; i < bytes.length; i += 3) {
    const n = (bytes[i] << 16) | ((bytes[i + 1] ?? 0) << 8) | (bytes[i + 2] ?? 0);
    saida += tabela[(n >> 18) & 63] + tabela[(n >> 12) & 63];
    if (i + 1 < bytes.length) saida += tabela[(n >> 6) & 63];
    if (i + 2 < bytes.length) saida += tabela[n & 63];
  }
  return saida;
}

// IOC "desarmado" para colar em chamado, e-mail ou chat sem virar link clicável:
// https://mal.com/x -> hxxps://mal[.]com/x ;  1.2.3.4 -> 1.2.3[.]4
function desarmar(ioc) {
  const texto = String(ioc ?? '');
  const url = texto.match(/^(https?)(:\/\/)([^/?#]*)(.*)$/i);
  if (!url) return texto.replace(/\./g, '[.]');
  return url[1].replace(/tt/i, 'xx') + url[2] + url[3].replace(/\./g, '[.]') + url[4];
}

// Escapa caracteres de controle e corta textos vindos de APIs/sites antes de irem para a IA.
function textoCurto(texto, maximo = 200) {
  return String(texto ?? '').replace(/[\u0000-\u001f\u007f<>`]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, maximo);
}
// ---- fim da biblioteca ----

// Nó "Consolidar inteligência": junta o que as fontes de reputação disseram, aponta sinais de risco
// e calcula um veredito e uma nota AUTOMÁTICOS (0 a 100, quanto maior, mais seguro).
// Eles servem de base para a IA analista SOC e de reserva se a IA falhar.
//
// Cuidado com falso positivo: plataformas grandes (github.com, drive.google.com...) hospedam
// arquivos de terceiros e aparecem no URLhaus/ThreatFox por causa de UMA URL. Por isso só o
// casamento EXATO com a URL ou o host analisado pesa forte, e domínios populares pesam menos.
const a = $input.first().json.auditoria;
const agora = Date.now();

// Respostas guardadas no Redis numa análise recente da mesma URL (nó "Usar cache").
let cache = { hit: false, respostas: {}, em: '' };
try { cache = $('Usar cache').first().json; } catch (erro) { /* sem cache */ }

function resposta(nome) {
  let json;
  if (cache.hit && cache.respostas?.[nome]) {
    json = cache.respostas[nome];
  } else {
    try {
      json = $(nome).first().json;
    } catch (erro) {
      return { executada: false, ok: false, status: 0, corpo: null, erro: 'não consultada' };
    }
  }
  if (json.error && json.statusCode === undefined) {
    return { executada: true, ok: false, status: 0, corpo: null, erro: textoCurto(json.error.message ?? json.error, 120) };
  }
  let corpo = json.body ?? null;
  if (typeof corpo === 'string') {
    try { corpo = JSON.parse(corpo); } catch (erro) { /* resposta não é JSON */ }
  }
  const status = Number(json.statusCode ?? 0);
  return { executada: true, ok: status >= 200 && status < 300, status, corpo, erro: status >= 300 ? `HTTP ${status}` : '' };
}

function erroDeFonte(r) {
  if (r.status === 401 || r.status === 403) return 'chave inválida ou sem permissão';
  if (r.status === 429) return 'cota esgotada (limite de consultas)';
  return r.erro || 'sem resposta';
}

const fontes = {};
const sinais = [];
const sinal = (fonte, nivel, pontos, texto) => sinais.push({ fonte, nivel, pontos, texto: textoCurto(texto, 300) });
const consultadas = [];
const falharam = [];
const registra = (nome, deuCerto, motivo) => (deuCerto ? consultadas.push(nome) : falharam.push(`${nome}: ${motivo}`));

// Domínio popular (top 100 mil em algum ranking do VirusTotal ou na lista de confiáveis do OTX)?
// Calculado antes dos sinais, porque reduz o peso de listagens "do host" em plataformas grandes.
let popular = false;
{
  const ranks = Object.values(resposta('VirusTotal (domínio)').corpo?.data?.attributes?.popularity_ranks ?? {}).map((v) => Number(v?.rank)).filter((x) => x > 0);
  const otx = resposta('OTX').corpo?.validation ?? [];
  popular = ranks.some((x) => x <= 100000) || otx.some((v) => /whitelist/i.test(`${v.source} ${v.name}`));
}

// ---------------- VirusTotal: domínio (ou IP) ----------------
{
  const r = resposta('VirusTotal (domínio)');
  const at = r.corpo?.data?.attributes;
  if (r.ok && at) {
    const stats = at.last_analysis_stats ?? {};
    const ranks = Object.entries(at.popularity_ranks ?? {}).map(([fonte, v]) => ({ fonte, rank: Number(v?.rank) })).filter((x) => x.rank > 0);
    const melhorRank = ranks.length ? Math.min(...ranks.map((x) => x.rank)) : null;
    const cert = at.last_https_certificate;
    const validoAte = cert?.validity?.not_after ? Date.parse(cert.validity.not_after.replace(' ', 'T') + 'Z') : NaN;
    fontes.vtDominio = {
      malicioso: Number(stats.malicious ?? 0),
      suspeito: Number(stats.suspicious ?? 0),
      inofensivo: Number(stats.harmless ?? 0),
      naoDetectado: Number(stats.undetected ?? 0),
      reputacao: Number(at.reputation ?? 0),
      categorias: [...new Set(Object.values(at.categories ?? {}).map((c) => textoCurto(c, 60)))].slice(0, 6),
      motores: Object.entries(at.last_analysis_results ?? {}).filter(([, v]) => v?.category === 'malicious' || v?.category === 'suspicious').map(([motor, v]) => textoCurto(`${motor}: ${v.result}`, 60)).slice(0, 8),
      melhorRank,
      fonteRank: ranks.find((x) => x.rank === melhorRank)?.fonte ?? '',
      criadoEm: at.creation_date ? new Date(at.creation_date * 1000).toISOString().slice(0, 10) : '',
      registrador: textoCurto(at.registrar, 80),
      pais: textoCurto(at.country, 4),
      asn: at.asn ? `AS${at.asn} ${textoCurto(at.as_owner, 60)}` : '',
      certEmissor: textoCurto(cert?.issuer?.O ?? cert?.issuer?.CN, 80),
      certValidoAte: Number.isFinite(validoAte) ? new Date(validoAte).toISOString().slice(0, 10) : '',
      certDiasRestantes: Number.isFinite(validoAte) ? Math.floor((validoAte - agora) / 86400000) : null,
      link: `https://www.virustotal.com/gui/${a.ehIP ? 'ip-address' : 'domain'}/${encodeURIComponent(a.dominio)}`,
    };
    registra('VirusTotal (domínio)', true);
    const d = fontes.vtDominio;
    if (d.malicioso >= 5) sinal('VirusTotal', 'malicioso', 40, `${d.malicioso} motores marcam ${a.dominio} como malicioso.`);
    else if (d.malicioso >= 2) sinal('VirusTotal', popular ? 'info' : 'suspeito', popular ? 5 : 15, `${d.malicioso} motores marcam ${a.dominio} como malicioso${popular ? ' (domínio muito acessado: possível falso positivo)' : ''}.`);
    else if (d.malicioso === 1) sinal('VirusTotal', 'info', popular ? 0 : 5, `Só 1 motor marca ${a.dominio} como malicioso (${d.motores[0] ?? ''}). Detecção isolada costuma ser falso positivo.`);
    if (d.reputacao <= -10) sinal('VirusTotal', 'suspeito', 10, `Reputação da comunidade do VirusTotal negativa (${d.reputacao}).`);
    if (d.certDiasRestantes !== null && d.certDiasRestantes < 0) sinal('Certificado', 'suspeito', 10, `O último certificado HTTPS visto pelo VirusTotal expirou em ${d.certValidoAte}.`);
  } else if (r.executada) {
    registra('VirusTotal (domínio)', false, r.status === 404 ? 'domínio desconhecido' : erroDeFonte(r));
    if (r.status === 404) sinal('VirusTotal', 'suspeito', 10, `${a.dominio} nunca foi visto pelo VirusTotal: típico de domínio recém-criado.`);
  }
}

// ---------------- VirusTotal: URL exata ----------------
{
  const r = resposta('VirusTotal (URL)');
  const at = r.corpo?.data?.attributes;
  if (r.ok && at) {
    const stats = at.last_analysis_stats ?? {};
    fontes.vtUrl = {
      malicioso: Number(stats.malicious ?? 0),
      suspeito: Number(stats.suspicious ?? 0),
      inofensivo: Number(stats.harmless ?? 0),
      titulo: textoCurto(at.title, 120),
      ultimaAnalise: at.last_analysis_date ? new Date(at.last_analysis_date * 1000).toISOString().slice(0, 10) : '',
      motores: Object.entries(at.last_analysis_results ?? {}).filter(([, v]) => v?.category === 'malicious' || v?.category === 'suspicious').map(([motor, v]) => textoCurto(`${motor}: ${v.result}`, 60)).slice(0, 8),
      link: `https://www.virustotal.com/gui/url/${encodeURIComponent($('Preparar consultas').first().json.vtUrlId)}`,
    };
    registra('VirusTotal (URL)', true);
    const u = fontes.vtUrl;
    if (u.malicioso >= 3) sinal('VirusTotal', 'malicioso', 50, `${u.malicioso} motores marcam esta URL como maliciosa (${u.motores.slice(0, 3).join('; ')}).`);
    else if (u.malicioso >= 1 || u.suspeito >= 2) sinal('VirusTotal', popular ? 'info' : 'suspeito', popular ? 5 : 15, `${u.malicioso} detecção(ões) maliciosa(s) e ${u.suspeito} suspeita(s) para esta URL.`);
  } else if (r.executada) {
    if (r.status === 404) {
      fontes.vtUrl = { naoVista: true };
      registra('VirusTotal (URL)', true);
    } else registra('VirusTotal (URL)', false, erroDeFonte(r));
  }
}

// ---------------- URLhaus (abuse.ch): host distribuindo malware ----------------
{
  const r = resposta('URLhaus');
  const c = r.corpo;
  if (r.ok && c && (c.query_status === 'ok' || c.query_status === 'no_results')) {
    const urls = Array.isArray(c.urls) ? c.urls : [];
    const exata = urls.find((u) => [a.urlFinal, a.urlOriginal].map((x) => String(x).replace(/\/$/, '')).includes(String(u.url).replace(/\/$/, '')));
    const dbl = String(c.blacklists?.spamhaus_dbl ?? 'not listed');
    fontes.urlhaus = {
      listado: c.query_status === 'ok',
      totalUrls: Number(c.url_count ?? 0),
      online: urls.filter((u) => u.url_status === 'online').length,
      ameacas: [...new Set(urls.flatMap((u) => [u.threat, ...(u.tags ?? [])]).filter(Boolean).map((t) => textoCurto(t, 40)))].slice(0, 6),
      spamhausDbl: textoCurto(dbl, 40),
      exata: exata ? { status: textoCurto(exata.url_status, 20), ameaca: textoCurto(exata.threat, 40) } : null,
      link: c.urlhaus_reference ?? '',
    };
    registra('URLhaus', true);
    const u = fontes.urlhaus;
    if (u.exata) sinal('URLhaus', u.exata.status === 'online' ? 'malicioso' : 'suspeito', u.exata.status === 'online' ? 50 : 25, `Esta URL está no URLhaus (${u.exata.ameaca}, ${u.exata.status}).`);
    if (dbl !== 'not listed' && dbl !== '') sinal('Spamhaus DBL', popular ? 'suspeito' : 'malicioso', popular ? 10 : 35, `Domínio na lista Spamhaus DBL (${u.spamhausDbl}).`);
    if (!u.exata && u.listado) {
      if (popular) sinal('URLhaus', 'info', 0, `${u.totalUrls} URL(s) deste host já distribuíram malware. Plataformas grandes hospedam arquivos de terceiros: avalie a URL, não o domínio.`);
      else if (u.online > 0) sinal('URLhaus', 'malicioso', 35, `${u.online} URL(s) deste host distribuem malware agora (${u.ameacas.join(', ')}).`);
      else sinal('URLhaus', 'suspeito', 10, `Este host já distribuiu malware (${u.totalUrls} URL(s), hoje fora do ar).`);
    }
  } else if (r.executada) registra('URLhaus', false, erroDeFonte(r));
}

// ---------------- ThreatFox (abuse.ch): IOC de malware/C2 ----------------
{
  const r = resposta('ThreatFox');
  const c = r.corpo;
  if (r.ok && c && (c.query_status === 'ok' || c.query_status === 'no_result')) {
    const iocs = Array.isArray(c.data) ? c.data : [];
    const limpa = (x) => String(x ?? '').toLowerCase().replace(/\/$/, '');
    const alvos = [a.host, a.dominio, a.urlFinal, a.urlOriginal].map(limpa);
    const exatos = iocs.filter((i) => alvos.includes(limpa(i.ioc)) || alvos.includes(limpa(i.ioc).replace(/:\d+$/, '')));
    fontes.threatfox = {
      total: iocs.length,
      exatos: exatos.map((i) => ({ malware: textoCurto(i.malware_printable, 50), tipo: textoCurto(i.threat_type, 30), confianca: Number(i.confidence_level ?? 0) })).slice(0, 5),
    };
    registra('ThreatFox', true);
    const t = fontes.threatfox;
    if (t.exatos.length) sinal('ThreatFox', 'malicioso', 45, `IOC conhecido de ${t.exatos.map((x) => `${x.malware} (${x.tipo}, confiança ${x.confianca})`).join('; ')}.`);
    else if (t.total > 0) sinal('ThreatFox', popular ? 'info' : 'suspeito', popular ? 0 : 15, `${t.total} IOC(s) de malware em URLs deste host${popular ? ' (plataforma popular, conteúdo de terceiros)' : ''}.`);
  } else if (r.executada) registra('ThreatFox', false, erroDeFonte(r));
}

// ---------------- OTX (AlienVault) ----------------
{
  const r = resposta('OTX');
  const c = r.corpo;
  if (r.ok && c) {
    const validacao = (c.validation ?? []).map((v) => textoCurto(v.name ?? v.source, 40));
    const confiavel = (c.validation ?? []).some((v) => /whitelist/i.test(`${v.source} ${v.name}`));
    fontes.otx = { pulsos: Number(c.pulse_info?.count ?? 0), confiavel, validacao: validacao.slice(0, 4) };
    registra('OTX', true);
    if (fontes.otx.pulsos > 0 && !confiavel) sinal('OTX', 'suspeito', 10, `Aparece em ${fontes.otx.pulsos} relatório(s) de ameaça da comunidade OTX.`);
  } else if (r.executada) registra('OTX', false, erroDeFonte(r));
}

// ---------------- AbuseIPDB (IP do servidor) ----------------
if (a.ipPrincipal) {
  const r = resposta('AbuseIPDB');
  const d = r.corpo?.data;
  if (r.ok && d) {
    fontes.abuseipdb = {
      ip: a.ipPrincipal,
      pontuacao: Number(d.abuseConfidenceScore ?? 0),
      denuncias: Number(d.totalReports ?? 0),
      uso: textoCurto(d.usageType, 60),
      provedor: textoCurto(d.isp, 80),
      pais: textoCurto(d.countryCode, 4),
      tor: Boolean(d.isTor),
      confiavel: Boolean(d.isWhitelisted),
    };
    registra('AbuseIPDB', true);
    const b = fontes.abuseipdb;
    if (b.pontuacao >= 75) sinal('AbuseIPDB', 'suspeito', 15, `IP ${b.ip} com ${b.pontuacao}% de confiança de abuso (${b.denuncias} denúncias). Em hospedagem compartilhada o IP pode ser de outro site.`);
    else if (b.pontuacao >= 25) sinal('AbuseIPDB', 'info', 5, `IP ${b.ip} com ${b.pontuacao}% de confiança de abuso.`);
    if (b.tor) sinal('AbuseIPDB', 'suspeito', 10, `IP ${b.ip} é nó da rede Tor.`);
  } else if (r.executada) registra('AbuseIPDB', false, erroDeFonte(r));
}

// ---------------- Shodan InternetDB (portas e CVEs conhecidas do IP) ----------------
if (a.ipPrincipal) {
  const r = resposta('Shodan InternetDB');
  const PORTAS_RISCO = { 21: 'FTP', 23: 'Telnet', 445: 'SMB', 1433: 'SQL Server', 3306: 'MySQL', 3389: 'RDP', 5432: 'PostgreSQL', 5900: 'VNC', 6379: 'Redis', 9200: 'Elasticsearch', 11211: 'Memcached', 27017: 'MongoDB' };
  if (r.ok && r.corpo) {
    const portas = (r.corpo.ports ?? []).map(Number).slice(0, 30);
    fontes.internetdb = {
      ip: a.ipPrincipal,
      portas,
      portasRisco: portas.filter((p) => PORTAS_RISCO[p]).map((p) => `${p} (${PORTAS_RISCO[p]})`),
      cves: (r.corpo.vulns ?? []).map((v) => textoCurto(v, 20)).slice(0, 15),
      totalCves: (r.corpo.vulns ?? []).length,
      tags: (r.corpo.tags ?? []).map((t) => textoCurto(t, 30)).slice(0, 6),
    };
    registra('Shodan InternetDB', true);
    const s = fontes.internetdb;
    if (s.portasRisco.length) sinal('Shodan', 'info', 8, `Serviços sensíveis expostos na internet no IP ${s.ip}: ${s.portasRisco.join(', ')}.`);
    if (s.totalCves) sinal('Shodan', 'info', 10, `O Shodan associa ${s.totalCves} CVE(s) ao IP ${s.ip} pela versão dos serviços (ex.: ${s.cves.slice(0, 3).join(', ')}). Confirme antes de concluir.`);
    if (s.tags.some((t) => /malware|c2|compromised/i.test(t))) sinal('Shodan', 'suspeito', 15, `Shodan marca o IP com: ${s.tags.join(', ')}.`);
  } else if (r.executada && r.status === 404) {
    fontes.internetdb = { ip: a.ipPrincipal, portas: [], portasRisco: [], cves: [], totalCves: 0, tags: [], semDados: true };
    registra('Shodan InternetDB', true);
  } else if (r.executada) registra('Shodan InternetDB', false, erroDeFonte(r));
}

// ---------------- RDAP: idade do domínio ----------------
if (!a.ehIP) {
  const r = resposta('RDAP (registro do domínio)');
  const eventos = r.corpo?.events ?? [];
  const data = (acao) => eventos.find((e) => e.eventAction === acao)?.eventDate ?? '';
  const registrador = (r.corpo?.entities ?? []).find((e) => (e.roles ?? []).includes('registrar'));
  const nomeRegistrador = (registrador?.vcardArray?.[1] ?? []).find((v) => v[0] === 'fn')?.[3] ?? '';
  let criado = data('registration') || fontes.vtDominio?.criadoEm || '';
  if (r.ok || criado) {
    const idadeDias = criado ? Math.floor((agora - Date.parse(criado)) / 86400000) : null;
    fontes.registro = {
      criadoEm: criado ? criado.slice(0, 10) : '',
      expiraEm: data('expiration').slice(0, 10),
      idadeDias: Number.isFinite(idadeDias) ? idadeDias : null,
      registrador: textoCurto(nomeRegistrador || fontes.vtDominio?.registrador, 80),
    };
    if (r.ok) registra('RDAP', true); else registra('RDAP', false, erroDeFonte(r) + ' (data veio do VirusTotal)');
    const idade = fontes.registro.idadeDias;
    if (idade !== null && idade < 30) sinal('Registro do domínio', 'suspeito', 25, `Domínio registrado há só ${idade} dia(s) (${fontes.registro.criadoEm}). Domínios novos são muito usados em phishing.`);
    else if (idade !== null && idade < 180) sinal('Registro do domínio', 'info', 10, `Domínio relativamente novo: ${idade} dias.`);
  } else if (r.executada) registra('RDAP', false, erroDeFonte(r));
}

// ---------------- DNS: proteção contra falsificação de e-mail (SPF/DMARC) e DNSSEC ----------------
if (!a.ehIP) {
  const txt = (nome) => {
    const r = resposta(nome);
    return { ok: r.ok, registros: (r.corpo?.Answer ?? []).filter((x) => x.type === 16).map((x) => String(x.data).replace(/^"|"$/g, '').replace(/"\s*"/g, '')) };
  };
  const spf = txt('DNS (SPF)');
  const dmarc = txt('DNS (DMARC)');
  const regSpf = spf.registros.find((x) => /^v=spf1/i.test(x)) ?? '';
  const regDmarc = dmarc.registros.find((x) => /^v=DMARC1/i.test(x)) ?? '';
  const politica = (regDmarc.match(/;\s*p=(\w+)/i) ?? [])[1]?.toLowerCase() ?? '';
  fontes.dnsEmail = { consultado: spf.ok || dmarc.ok, spf: textoCurto(regSpf, 200), dmarc: textoCurto(regDmarc, 200), politicaDmarc: politica, dnssec: Boolean(a.dnssec) };
  if (fontes.dnsEmail.consultado) {
    if (!regSpf) sinal('DNS', 'info', 3, `${a.dominio} não tem SPF: qualquer servidor pode mandar e-mail se passando pelo domínio.`);
    if (!regDmarc) sinal('DNS', 'info', 3, `${a.dominio} não tem DMARC: e-mails falsificados com o domínio não são rejeitados.`);
    else if (politica === 'none') sinal('DNS', 'info', 1, 'DMARC só monitora (p=none): e-mails falsificados ainda são entregues.');
  }
}

// ---------------- Mozilla Observatory (segunda opinião sobre a postura) ----------------
{
  const r = resposta('Mozilla Observatory');
  if (r.ok && r.corpo && !r.corpo.error) {
    fontes.observatory = {
      nota: textoCurto(r.corpo.grade, 4),
      pontos: Number(r.corpo.score ?? 0),
      testesFalhos: Number(r.corpo.tests_failed ?? 0),
      testesTotal: Number(r.corpo.tests_quantity ?? 0),
      link: `https://developer.mozilla.org/en-US/observatory/analyze?host=${encodeURIComponent(a.host)}`,
    };
    registra('Mozilla Observatory', true);
  } else if (r.executada) registra('Mozilla Observatory', false, r.corpo?.error ? textoCurto(r.corpo.error, 80) : erroDeFonte(r));
}

// ---------------- urlscan.io: histórico e análise num navegador real ----------------
{
  const busca = resposta('urlscan (busca)');
  const resultados = Array.isArray(busca.corpo?.results) ? busca.corpo.results : [];
  const envio = resposta('urlscan (enviar análise)');
  const nova = resposta('urlscan (resultado)');
  const anterior = resposta('urlscan (última análise)');

  if (busca.ok || envio.executada) {
    const historico = {
      total: Number(busca.corpo?.total ?? resultados.length),
      ultimas: resultados.slice(0, 5).map((r) => ({
        data: textoCurto(r.task?.time, 10),
        url: textoCurto(r.page?.url ?? r.task?.url, 160),
        tags: (r.task?.tags ?? []).map((t) => textoCurto(t, 30)).slice(0, 4),
      })),
      // Tags vêm de quem enviou a análise (inclusive robôs) e erram muito: só informam.
      tags: [...new Set(resultados.flatMap((r) => r.task?.tags ?? []).map((t) => textoCurto(t, 30)))].slice(0, 8),
    };

    // Lê um resultado completo (análise nova ou anterior) no mesmo formato.
    const ler = (r, propria) => {
      const c = r.corpo;
      if (!r.ok || !c?.task) return null;
      const geral = c.verdicts?.overall ?? {};
      const marcas = (geral.brands ?? []).map((b) => textoCurto(typeof b === 'string' ? b : b?.name ?? b?.key, 40)).filter(Boolean);
      return {
        propria,
        uuid: textoCurto(c.task.uuid, 40),
        data: textoCurto(c.task.time, 10),
        visibilidade: textoCurto(c.task.visibility, 12),
        url: textoCurto(c.page?.url, 200),
        titulo: textoCurto(c.page?.title, 120),
        dominioFinal: textoCurto(c.page?.domain, 100),
        ip: textoCurto(c.page?.ip, 45),
        pais: textoCurto(c.page?.country, 4),
        asn: textoCurto(`${c.page?.asn ?? ''} ${c.page?.asnname ?? ''}`, 80),
        emissorTls: textoCurto(c.page?.tlsIssuer, 80),
        idadeTlsDias: Number.isFinite(Number(c.page?.tlsAgeDays)) ? Number(c.page.tlsAgeDays) : null,
        malicioso: Boolean(geral.malicious),
        pontuacao: Number(geral.score ?? 0),
        marcas,
        categorias: (geral.categories ?? []).map((x) => textoCurto(x, 30)).slice(0, 5),
        dominiosContatados: (c.lists?.domains ?? []).map((d) => textoCurto(d, 80)).slice(0, 15),
        totalDominios: (c.lists?.domains ?? []).length,
        totalIps: (c.lists?.ips ?? []).length,
        paises: (c.lists?.countries ?? []).map((x) => textoCurto(x, 4)).slice(0, 8),
        link: `https://urlscan.io/result/${encodeURIComponent(c.task.uuid)}/`,
        print: `https://urlscan.io/screenshots/${encodeURIComponent(c.task.uuid)}.png`,
      };
    };

    let analise = ler(nova, true) ?? ler(anterior, false);
    let erroEnvio = '';
    if (envio.executada && !envio.corpo?.uuid) {
      erroEnvio = textoCurto(envio.corpo?.message ?? envio.corpo?.description ?? erroDeFonte(envio), 160);
    } else if (envio.executada && !ler(nova, true)) {
      erroEnvio = nova.status === 404 ? 'a análise não terminou a tempo (veja depois no link)' : erroDeFonte(nova);
      analise = ler(anterior, false);
    }
    fontes.urlscan = {
      historico,
      analise,
      erroEnvio,
      linkPendente: envio.corpo?.uuid && !analise?.propria ? `https://urlscan.io/result/${encodeURIComponent(envio.corpo.uuid)}/` : '',
    };
    registra('urlscan.io', Boolean(analise) || busca.ok, erroEnvio || erroDeFonte(busca));
    if (erroEnvio) falharam.push(`urlscan.io (análise nova): ${erroEnvio}`);

    if (analise) {
      const quando = analise.propria ? 'na análise feita agora' : `na análise de ${analise.data}`;
      const diasAtras = analise.data ? Math.floor((agora - Date.parse(analise.data)) / 86400000) : 999;
      const recente = analise.propria || diasAtras <= 30;
      if (analise.malicioso) {
        sinal('urlscan.io', recente ? 'malicioso' : 'suspeito', recente ? 45 : 15, `O urlscan.io classificou a página como maliciosa ${quando}${analise.categorias.length ? ` (${analise.categorias.join(', ')})` : ''}.`);
      }
      const dominioMarca = (m) => String(m).toLowerCase().replace(/[^a-z0-9]/g, '');
      const imitada = analise.marcas.filter((m) => dominioMarca(m) && !String(a.dominio).replace(/[^a-z0-9]/g, '').includes(dominioMarca(m)));
      if (imitada.length) sinal('urlscan.io', 'suspeito', 20, `A página parece imitar a marca ${imitada.join(', ')} ${quando}, mas o domínio é ${a.dominio}.`);
      if (analise.dominioFinal && analise.dominioFinal !== a.host && !analise.dominioFinal.endsWith(`.${a.dominio}`) && analise.dominioFinal !== a.dominio) {
        sinal('urlscan.io', 'info', 5, `No navegador do urlscan a página terminou em outro domínio: ${analise.dominioFinal} (redirecionamento por JavaScript?).`);
      }
    }
  } else if (busca.executada) registra('urlscan.io', false, erroDeFonte(busca));
}

// ---------------- Postura (só se o site foi visitado) ----------------
if (a.visitado) {
  const PESO_NOTA = { 'A+': 0, A: 0, 'A-': 0, 'B+': 3, B: 3, 'B-': 3, 'C+': 6, C: 6, 'C-': 6, D: 10, F: 12 };
  if (PESO_NOTA[a.nota]) sinal('Postura', 'info', PESO_NOTA[a.nota], `Cabeçalhos de segurança com nota ${a.nota} (${a.totalAlto} problema(s) alto(s), ${a.totalMedio} médio(s)).`);
  if (!a.ehHttps) sinal('Postura', 'suspeito', 10, 'A página é servida sem HTTPS: qualquer senha digitada trafega aberta.');
}
if (a.avisoDns) sinal('DNS', 'info', 0, a.avisoDns);

// ---------------- Veredito e nota automáticos ----------------
const REPUTACAO = ['VirusTotal (domínio)', 'VirusTotal (URL)', 'URLhaus', 'ThreatFox', 'OTX', 'AbuseIPDB', 'urlscan.io'];
const fontesReputacao = consultadas.filter((f) => REPUTACAO.includes(f)).length;
let veredito;
if (sinais.some((s) => s.nivel === 'malicioso')) veredito = 'malicioso';
else if (sinais.some((s) => s.nivel === 'suspeito')) veredito = 'suspeito';
else if (fontesReputacao >= 3) veredito = 'limpo';
else veredito = 'indeterminado';

let nota = Math.max(0, 100 - sinais.reduce((soma, s) => soma + s.pontos, 0));
if (veredito === 'malicioso') nota = Math.min(nota, 20);
if (veredito === 'suspeito') nota = Math.min(nota, 60);

const ORDEM = { malicioso: 0, suspeito: 1, info: 2 };
sinais.sort((x, y) => ORDEM[x.nivel] - ORDEM[y.nivel] || y.pontos - x.pontos);

return [{
  json: {
    auditoria: {
      ...a,
      inteligencia: {
        fontes,
        sinais,
        popular,
        consultadas,
        falharam,
        fontesReputacao,
        vereditoAutomatico: veredito,
        notaAutomatica: nota,
        cache: { usado: Boolean(cache.hit), em: cache.hit ? cache.em : '' },
      },
    },
  },
}];

// Nó "Montar cache": guarda no Redis as respostas das fontes de reputação desta análise,
// já enxutas (sem o que o relatório não usa), para a próxima análise da mesma URL não gastar cota.
// Fica 24 h (configurável); se alguma fonte falhou, só 1 h, para tentar de novo logo.
const VERSAO = 1;
const FONTES = [
  'urlscan (busca)', 'urlscan (enviar análise)', 'urlscan (resultado)', 'urlscan (última análise)',
  'VirusTotal (URL)', 'VirusTotal (domínio)', 'URLhaus', 'ThreatFox', 'OTX', 'AbuseIPDB',
  'Shodan InternetDB', 'RDAP (registro do domínio)', 'DNS (SPF)', 'DNS (DMARC)',
];
const alvo = $('Preparar consultas').first().json;
const config = $('Configuração').first().json;
const intel = $('Consolidar inteligência').first().json.auditoria.inteligencia;

function enxugar(nome, body) {
  if (!body || typeof body !== 'object') return body;
  const c = JSON.parse(JSON.stringify(body));
  if (nome.startsWith('VirusTotal') && c.data?.attributes) {
    const at = c.data.attributes;
    for (const campo of ['whois', 'rdap', 'last_dns_records', 'jarm', 'tags', 'total_votes', 'html_meta', 'trackers', 'outgoing_links', 'redirection_chain']) delete at[campo];
    at.last_analysis_results = Object.fromEntries(Object.entries(at.last_analysis_results ?? {})
      .filter(([, v]) => v?.category === 'malicious' || v?.category === 'suspicious'));
    if (at.last_https_certificate) at.last_https_certificate = { validity: at.last_https_certificate.validity, issuer: at.last_https_certificate.issuer };
  }
  if (nome === 'urlscan (resultado)' || nome === 'urlscan (última análise)') {
    delete c.data;
    delete c.meta;
    if (c.lists) c.lists = { domains: c.lists.domains, ips: c.lists.ips, countries: c.lists.countries };
  }
  if (nome === 'urlscan (busca)' && Array.isArray(c.results)) {
    c.results = c.results.map((r) => ({ _id: r._id, task: { time: r.task?.time, tags: r.task?.tags, url: r.task?.url }, page: { url: r.page?.url } }));
  }
  if (nome === 'URLhaus' && Array.isArray(c.urls)) {
    c.urls = c.urls.slice(0, 100).map((u) => ({ url: u.url, url_status: u.url_status, threat: u.threat, tags: u.tags }));
  }
  if (nome === 'ThreatFox' && Array.isArray(c.data)) c.data = c.data.slice(0, 50);
  if (nome === 'RDAP (registro do domínio)') c.entities = (c.entities ?? []).filter((e) => (e.roles ?? []).includes('registrar')).map((e) => ({ roles: e.roles, vcardArray: e.vcardArray }));
  return c;
}

const respostas = {};
for (const nome of FONTES) {
  let json;
  try { json = $(nome).first().json; } catch (erro) { continue; }
  if (json.statusCode === undefined) continue; // erro de rede: não guarda, a próxima análise tenta de novo
  respostas[nome] = { statusCode: json.statusCode, body: enxugar(nome, json.body) };
}

const horas = Math.max(1, Number(config.cacheHoras) || 24);
const ttl = intel.falharam.length ? 3600 : horas * 3600;

return [{
  json: {
    chave: alvo.chaveCache,
    ttl,
    valor: JSON.stringify({ versao: VERSAO, urlFinal: alvo.urlFinal, em: new Date().toISOString(), respostas }),
  },
}];

